  "termsScreen": {
    "paragraph1": "Sabi استعمال کرنے سے آپ اس بات سے متفق ہوتے ہیں کہ والیٹ فیچرز، رابطہ کاری، لین دین اور ڈیجیٹل سروسز کے استعمال کے لیے مقررہ پلیٹ فارم قواعد، نافذ العمل قوانین اور سیکیورٹی تقاضوں کی پابندی کریں گے۔",
    "paragraph2": "صارف فراہم کردہ معلومات کی درستگی، اپنے آلات کے تحفظ، اکاؤنٹ تک رسائی کے کنٹرول اور نظام کے اندر انجام دیے جانے والے اعمال کی قانونی حیثیت کا ذمہ دار ہے۔",
    "paragraph3": "Sabi مصنوعات کو بہتر بنانے، ضابطہ جاتی تقاضوں کی تکمیل اور صارفین کے تحفظ کے لیے فعالیت، سیکیورٹی تقاضوں، استعمال کے قواعد اور مخصوص سروس شرائط کو اپ ڈیٹ کر سکتا ہے۔",
    "paragraph4": "شرائط کی تازہ کاری کے بعد پلیٹ فارم کا استعمال جاری رکھنا سروس قواعد کے موجودہ ورژن سے اتفاق تصور کیا جائے گا۔"
  },
